#include "EffectRuntimeFixture.hpp"
#include <item/EquipmentStats.hpp>
#include <iostream>
#include <fstream>
#include <iomanip>
#include <stdexcept>
using namespace auriga::item;namespace f=effect_runtime_fixture;namespace pf=persistent_item_fixture;
static int checks=0;void Check(bool v,const char* m){++checks;if(!v)throw std::runtime_error(m);}
int main(int argc,char** argv){try{
 const auto c=BuildItemCatalog(f::Catalog()).value();auto facts=f::Facts();ItemOwnerFence fence{pf::Character(),7,1};const std::array layouts{pf::Inventory()};RecoverySchedule state;std::vector<PersistentItem> items;for(unsigned i=0;i<10;++i)items.push_back(f::Item(*c,i,70+i));
 const auto use=[&](unsigned index,std::uint64_t elapsed,std::uint64_t now,std::uint64_t effect){return MakeItemEffectUse(*c,{21,static_cast<std::uint8_t>(fence.revision)},fence,layouts,items,state,items[index].id,facts,elapsed,now,effect);};
 const auto apply=[&](const ItemCommit& commit){for(const auto& change:commit.items){auto found=std::ranges::find(items,change.after.id,&PersistentItem::id);Check(found!=items.end(),"fixture change identifies original");*found=change.after;}state=commit.recovery->after;++fence.revision;};
 auto wall=use(0,0,1000,100);Check(wall && wall->items[0].after.count==4,"wall item debited with schedule");apply(*wall);Check(state.effects[0].expiresAtMs==61000 && state.effects[0].remainingMs==0,"wall deadline stored independently of online elapsed");
 auto online=use(1,0,1000,101);Check(online.has_value(),"online effect applied alongside wall");apply(*online);Check(use(1,10,1010,102).error().code==14,"reject group cannot consume or stack");
 auto elapsed=AdvanceRecoverySchedule(*c,state,1234).value();NormalizeTimedItems(*c,elapsed,55000);Check(elapsed.effects.size()==2 && elapsed.effects[1].remainingMs==58766 && TimedItemRemaining(elapsed.effects[0],55000)==6000,"online and wall clocks diverge explicitly");NormalizeTimedItems(*c,elapsed,61000);Check(elapsed.effects.size()==1,"offline wall expiry does not remove online effect");
 auto death=state;auto dead=facts;dead.alive=false;NormalizeTimedItems(*c,death,1000,&dead);Check(death.effects.size()==1 && death.effects[0].source==f::Key(0),"group death rule retains non-removable wall effect");
 auto first=use(2,0,1000,102);Check(first.has_value(),"replace group starts");apply(*first);auto replace=use(3,100,1100,103);Check(replace.has_value(),"replace group accepts other package");apply(*replace);Check(state.effects.size()==3 && std::ranges::none_of(state.effects,[](const auto& e){return e.id==102;}),"whole previous effect identity replaced");
 auto bonuses=CollectItemEffectBonuses(*c,state,items).value();auto stats=BuildEquipmentStats(*c,pf::Character(),items,bonuses).value();Check(stats.Bonus(BonusId::Strength)==19 && stats.Bonus(BonusId::MovementSpeedPercent)==2500 && stats.flat.physicalAttackRaw==12000,"complete packages reach actual stat builder once");
 auto blob=EncodeRecoverySchedule(*c,state).value();Check(blob[3]=='2' && DecodeRecoverySchedule(*c,blob).value()==state,"RCS2 preserves full state");for(std::size_t n=0;n<blob.size();++n)Check(!DecodeRecoverySchedule(*c,std::span(blob).first(n)),"RCS2 truncation");auto trailing=blob;trailing.push_back(0);Check(!DecodeRecoverySchedule(*c,trailing),"RCS2 trailing data");auto malformed=state;malformed.effects[1].id=malformed.effects[0].id;Check(!ValidateRecoverySchedule(*c,malformed),"duplicate effect identities rejected");
 auto on=use(4,0,1100,104);Check(on && on->items[0].after.count==1,"toggle activation does not consume instance");apply(*on);Check(items[4].toggle->active,"toggle is durably active");Check(!MakeMoveCommit(*c,{21,77},fence,layouts,items,items[4].id,{ItemStorageKind::Inventory,1,40}),"active toggle cannot move");Check(!MakeConsumeCommit(*c,{21,78},fence,layouts,items,items[4].id,1),"active toggle cannot be consumed");
 auto off=use(4,123,1223,105);Check(off.has_value(),"fast toggle off admitted");apply(*off);Check(!items[4].toggle->active && items[4].toggle->remainingMs==59877,"fast off charges exact milliseconds");auto again=use(4,456,1679,106);Check(again.has_value(),"inactive duration survives later activation");apply(*again);Check(items[4].toggle->remainingMs==59877,"inactive elapsed is not charged");
 Check(use(6,1,1680,107).error().code==48,"same variant in another instance rejected");auto opposite=use(5,50,1729,108);Check(opposite.has_value(),"opposite variant replaces");apply(*opposite);Check(!items[4].toggle->active && items[5].toggle->active && items[4].toggle->remainingMs==59827,"atomic opposite replacement settles old interval");
 Check(use(7,0,1729,109).error().code==44 && use(8,0,1729,110).error().code==44,"marriage and party-leader gates");facts.married=facts.partyLeader=true;auto required=use(7,0,1729,111);Check(required.has_value(),"required role admits activation");apply(*required);auto lost=facts;lost.married=false;auto projected=ProjectToggleItems(*c,items,200,lost).value();Check(!projected[7].toggle->active && projected[7].toggle->remainingMs==59800,"role loss charges interval then deactivates");
 auto tiny=use(9,0,1729,112);Check(tiny.has_value(),"tiny toggle begins");apply(*tiny);ItemCommit timer;timer.operationId={21,80};timer.catalogRevision=c->Revision();timer.catalogHash=c->ContentHash();timer.kind=ItemOperationKind::Service;timer.owners={fence};timer.outcomeCode=0x2003;auto advanced=AdvanceRecoverySchedule(*c,state,1000).value();++advanced.revision;timer.recovery=ItemRecoveryChange{fence.owner,state,advanced,1000};Check(SettleToggleTime(*c,timer,layouts,items,1000,facts).has_value() && ValidateItemCommit(*c,timer).has_value(),"expiry settles with shared clock transaction");Check(std::ranges::any_of(timer.items,[&](const auto& i){return i.after.id==items[9].id && i.after.destroyed && i.after.toggle->remainingMs==0;}),"expired instance becomes tombstone");
 const auto wire=EncodeTypedInventory(*c,layouts,{},items).value();Check(std::to_integer<unsigned>(wire[5])==3 && DecodeTypedInventory(wire,fence.owner)->items[5].toggle==items[5].toggle,"inventory v3 preserves toggle state");
 auto cancel=MakeItemEffectCancel(*c,{21,90},fence,state,0,1729,state.generation,state.effects[0].id);Check(cancel && cancel->recovery->after.effects.size()==state.effects.size()-1,"cancel exact timed effect");Check(!MakeItemEffectCancel(*c,{21,91},fence,state,0,1729,state.generation-1,0),"stale generation cannot cancel newer effects");
 const auto packet=EncodeItemEffectsRuntime(*c,{1,255,123,456,&items[1],&state,items,1729});Check(packet.has_value(),"native effect runtime packet encodes all packages");
 if(argc==3 && std::string_view(argv[1])=="--golden-output"){std::ofstream output(argv[2]);for(auto b:*packet)output<<std::hex<<std::setw(2)<<std::setfill('0')<<std::to_integer<unsigned>(b);output<<'\n';}
 std::cout<<"Item effect runtime: "<<checks<<" checks passed\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
